<script lang="ts">
 import { onMount } from 'svelte'; import { request } from './api'; import { PageHeader, RefreshButton } from './ui';
 type Product={id:string;sku:string;name:string;price_cents:number;stock_qty:number};type Sale={id:string;receipt_number:string;total_cents:number;created_at:string};
 let products=$state<Product[]>([]),sales=$state<Sale[]>([]),sku=$state(''),name=$state(''),price=$state(0),stock=$state(0),error=$state(''),saving=$state(false);
 const money=(v:number)=>new Intl.NumberFormat('id-ID',{style:'currency',currency:'IDR',maximumFractionDigits:0}).format(v/100);
 async function load(){try{const x=await request<{products:Product[];sales:Sale[]}>('/v1/admin/pos');products=x.products;sales=x.sales;}catch(e){error=e instanceof Error?e.message:'POS tidak dapat dimuat.';}}
 async function add(){saving=true;try{await request('/v1/admin/pos/products',{method:'POST',body:JSON.stringify({sku,name,price_cents:Number(price),stock_qty:Number(stock)})});sku='';name='';price=0;stock=0;await load();}finally{saving=false;}}
 async function checkout(product:Product){saving=true;try{await request('/v1/admin/pos',{method:'POST',body:JSON.stringify({lines:[{product_id:product.id,quantity:1}]})});await load();}finally{saving=false;}}
 onMount(load);
</script>
<main class="workspace-page"><PageHeader title="Toko POS" description="Katalog, stok, kasir, dan receipt tenant dalam satu layar ringkas." backHref="/admin/dashboard"/>{#if error}<p class="alert">{error}</p>{/if}<div class="grid"><section class="panel"><h2>Produk</h2><form novalidate onsubmit={(e)=>{e.preventDefault();void add();}}><input bind:value={sku} placeholder="SKU" required/><input bind:value={name} placeholder="Nama produk" required/><input bind:value={price} type="number" min="0" placeholder="Harga (sen)"/><input bind:value={stock} type="number" min="0" placeholder="Stok"/><button disabled={saving}>Simpan produk</button></form></section><section class="panel"><header><h2>Katalog</h2><RefreshButton onclick={load} label="Muat ulang"/></header>{#each products as item (item.id)}<article><div><strong>{item.name}</strong><small>{item.sku} · stok {item.stock_qty}</small></div><div><strong>{money(item.price_cents)}</strong><button disabled={saving||item.stock_qty<1} onclick={()=>checkout(item)}>Jual 1</button></div></article>{:else}<p class="muted">Belum ada produk.</p>{/each}</section></div><section class="panel"><h2>Receipt terbaru</h2>{#each sales as sale (sale.id)}<article><strong>{sale.receipt_number}</strong><strong>{money(sale.total_cents)}</strong></article>{:else}<p class="muted">Belum ada transaksi.</p>{/each}</section></main>
<style>.workspace-page,.grid{display:grid;gap:12px}.grid{grid-template-columns:1fr 1fr}.panel{padding:16px;border-radius:var(--radius)}form{display:grid;gap:8px}article{display:grid;grid-template-columns:1fr auto;gap:8px;border-top:1px solid var(--line);padding:10px 0;align-items:center}article div:last-child{text-align:right}small{display:block;color:var(--muted);font-size:12px}.alert{color:var(--danger)}@media(max-width:720px){.grid{grid-template-columns:1fr}}</style>
